class Solution:
       def solve(self, grid: list) -> int:
           def is_valid_move(x, y):
               return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 0

           def dfs(x, y):
               if x == len(grid) - 1 and y == len(grid[0]) - 1:
                   return True
               grid[x][y] = 1
               directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
               for dx, dy in directions:
                   nx, ny = x + dx, y + dy
                   if is_valid_move(nx, ny) and dfs(nx, ny):
                       return True
               return False

           if dfs(0, 0):
               return 1
           return 0
